const json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { "content-type":"application/json; charset=utf-8", "cache-control":"no-store, max-age=0", "x-robots-tag":"noindex, nofollow" } });
const normalize = value => String(value || "").trim().toLowerCase();
const digest = async value => { const bytes=new TextEncoder().encode(value); const hash=await crypto.subtle.digest("SHA-256",bytes); return Array.from(new Uint8Array(hash)).map(byte=>byte.toString(16).padStart(2,"0")).join(""); };
export async function onRequestPost({ request }) {
  try {
    const body=await request.json(); const identifier=normalize(body?.identifier); const password=String(body?.password || "").trim();
    if (!identifier || !password || identifier.length>120 || password.length>200) return json({success:false,message:"Enter your student identifier and password."},400);
    const student=STUDENTS.find(item => [item.id,item.regNumber].some(value=>normalize(value)===identifier));
    const suppliedHash=await digest(PASSWORD_SALT+password);
    if (!student || suppliedHash!==student.passwordHash) return json({success:false,message:"Invalid student identifier or password."},401);
    const { passwordHash, ...result }=student; return json({success:true,student:result});
  } catch { return json({success:false,message:"Emergency results service is temporarily unavailable."},400); }
}
export async function onRequest({ request }) { return request.method === "POST" ? onRequestPost({request}) : json({success:false,message:"Use POST to sign in."},405); }
